/* eslint-disable @typescript-eslint/no-explicit-any */
'use client'
import { useState, useMemo } from 'react'
import { TrendingUp } from 'lucide-react'
import {
  Card,
  CardHeader,
  CardTitle,
  CardDescription,
  CardContent,
} from '@/components/ui/card'
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs'
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
} from 'recharts'
import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
} from '@/components/ui/chart'
import { useGetRevenueReport } from '@/lib/handleAllGetRequests'

const chartConfig = {
  revenue: {
    label: 'Revenue',
    color: 'hsl(var(--chart-1))',
  },
}

export default function RevenueChart() {
  const [period, setPeriod] = useState<'day' | 'week' | 'month' | 'year'>('day')
  const { data: revenueData, isLoading } = useGetRevenueReport(period)

  const revenue = useMemo(() => {
    const raw = revenueData?.data || []
    return raw.map((item: any) => {
      if (period === 'day') return { label: item.date, revenue: item.revenue }
      if (period === 'week') return { label: item.day, revenue: item.revenue }
      if (period === 'month')
        return { label: item.month, revenue: item.revenue }
      if (period === 'year')
        return { label: item.year?.toString(), revenue: item.revenue }
      return item
    })
  }, [revenueData?.data, period])

  if (isLoading)
    return <div className="h-80 bg-gray-200 rounded animate-pulse"></div>

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <TrendingUp className="h-5 w-5" />
          Revenue Report
        </CardTitle>
        <CardDescription>Revenue overview by time period</CardDescription>
      </CardHeader>
      <CardContent>
        <Tabs value={period} onValueChange={(val) => setPeriod(val as any)}>
          <TabsList className="grid w-full grid-cols-4 bg-[#E6E6E6] rounded-lg p-1">
            {['day', 'week', 'month', 'year'].map((p) => (
              <TabsTrigger
                key={p}
                value={p}
                className="px-2 py-1 rounded-md text-sm font-medium transition-colors data-[state=active]:bg-[#797068] data-[state=active]:text-white text-[#595959] cursor-pointer"
              >
                {p.charAt(0).toUpperCase() + p.slice(1)}
              </TabsTrigger>
            ))}
          </TabsList>
          <TabsContent value={period}>
            <ChartContainer config={chartConfig}>
              <ResponsiveContainer width="100%" height={300}>
                <LineChart data={revenue} margin={{ left: 12, right: 12 }}>
                  <CartesianGrid vertical={false} />
                  <XAxis
                    dataKey="label"
                    tickLine={false}
                    axisLine={false}
                    tickMargin={8}
                  />
                  <YAxis
                    tickLine={false}
                    axisLine={false}
                    tickMargin={8}
                    tickFormatter={(val) => `$${val}`}
                  />
                  <ChartTooltip
                    cursor={false}
                    content={<ChartTooltipContent />}
                  />
                  <Line
                    dataKey="revenue"
                    type="monotone"
                    stroke={chartConfig.revenue.color}
                    strokeWidth={2}
                    dot={{ fill: chartConfig.revenue.color }}
                    activeDot={{ r: 6 }}
                  />
                </LineChart>
              </ResponsiveContainer>
            </ChartContainer>
          </TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  )
}
